import json
import struct
import sys
import zlib

KIND_BEGIN = 1
KIND_PATCH = 2
KIND_COMMIT = 3
KIND_ABORT = 4

MAX_PAYLOAD = 4096


def solve(req):
    pages_in = req["pages"]
    checkpoint = int(req["checkpoint"])
    log = bytes.fromhex(req["log"])

    pages = [bytearray(bytes.fromhex(p)) for p in pages_in]
    num_pages = len(pages)
    page_len = len(pages[0]) if num_pages else 0

    n = len(log)
    pos = 0
    last_seq = 0
    # active incarnations: tid -> list of staged PATCH payload bytes
    active = {}

    while pos + 13 <= n:
        payload_len, seq = struct.unpack_from("<II", log, pos)
        kind = log[pos + 8]
        tid = struct.unpack_from("<I", log, pos + 9)[0]

        # Structural validation (no semantic effect until all pass).
        if payload_len > MAX_PAYLOAD:
            break
        end = pos + 13 + payload_len
        if end + 4 > n:
            break  # incomplete record / torn
        if seq == 0 or seq <= last_seq:
            break  # invalid sequence
        if tid == 0:
            break  # invalid transaction id
        if kind not in (KIND_BEGIN, KIND_PATCH, KIND_COMMIT, KIND_ABORT):
            break  # invalid kind

        payload = log[pos + 13:end]
        crc_stored = struct.unpack_from("<I", log, end)[0]
        crc_calc = zlib.crc32(log[pos:end]) & 0xFFFFFFFF
        if crc_stored != crc_calc:
            break  # invalid CRC

        if kind == KIND_BEGIN or kind == KIND_ABORT:
            if payload_len != 0:
                break
        elif kind == KIND_PATCH:
            if payload_len < 7:
                break
            page_index, byte_offset, byte_count = struct.unpack_from("<HHH", payload, 0)
            if byte_count == 0:
                break
            if payload_len != 6 + byte_count:
                break
            if page_index >= num_pages:
                break
            if byte_offset + byte_count > page_len:
                break
        else:  # COMMIT
            if payload_len != 8:
                break

        # Record is structurally valid: extend the valid prefix.
        pos = end + 4
        last_seq = seq

        # Semantic processing.
        if kind == KIND_BEGIN:
            active[tid] = []
        elif kind == KIND_PATCH:
            if tid in active:
                active[tid].append(payload)
        elif kind == KIND_ABORT:
            active.pop(tid, None)
        else:  # COMMIT
            staged = active.pop(tid, None)
            if staged is not None:
                count, digest = struct.unpack_from("<II", payload, 0)
                calc = zlib.crc32(b"".join(staged)) & 0xFFFFFFFF
                if count == len(staged) and digest == calc and seq > checkpoint:
                    for p in staged:
                        pi, off, bc = struct.unpack_from("<HHH", p, 0)
                        pages[pi][off:off + bc] = p[6:6 + bc]

    return {
        "pages": [bytes(p).hex() for p in pages],
        "valid_bytes": pos,
        "last_seq": last_seq,
    }


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        out.write(json.dumps(solve(req)) + "\n")
    out.flush()


if __name__ == "__main__":
    main()
